<template><PageShell title="Central de Guias" subtitle="Acompanhamento dos processos administrativos"><div class="panel grid gap-3 md:grid-cols-4"><input v-model="filters.search" class="input" placeholder="Paciente"><select v-model="filters.document_status" class="input"><option value="">Documentação: todos</option><option>INCOMPLETE</option><option>COMPLETE</option></select><select v-model="filters.authorization_status" class="input"><option value="">Autorização: todos</option><option v-for="s in authStatuses" :key="s">{{s}}</option></select><select v-model="filters.treatment_status" class="input"><option value="">Tratamento: todos</option><option>WAITING</option><option>IN_PROGRESS</option><option>COMPLETED</option></select><input v-model="filters.assessment_date" type="date" class="input"><input v-model="filters.expected_start_date" type="date" class="input"><select v-model="filters.billing_status" class="input"><option value="">Faturamento: todos</option><option>NOT_READY</option><option>READY</option><option>DELIVERED</option><option>BILLED</option></select><button class="btn" @click="load(1)">Filtrar</button></div><div class="panel overflow-x-auto"><table class="table"><thead><tr><th>Paciente</th><th>Convênio</th><th>Fisioterapeuta</th><th>Avaliação / início</th><th>Sessões</th><th>Documentos</th><th>Autorização</th><th>Tratamento</th><th>Faturamento</th><th>Prioridade</th></tr></thead><tbody><tr v-for="p in data" :key="p.id" class="cursor-pointer" @click="$router.push(`/central-de-guias/${p.id}`)"><td class="font-medium">{{p.patient_name}}</td><td>{{p.insurance_name}}</td><td>{{p.physiotherapist_name}}</td><td>{{date(p.assessment_date)}}<br>{{date(p.expected_start_date)}}</td><td>{{p.requested_sessions}} / {{p.authorized_sessions??'—'}}</td><td><span class="badge">{{p.document_status}}</span></td><td>{{p.authorization_status}}</td><td>{{p.treatment_status}}</td><td>{{p.billing_status}}</td><td>{{p.priority}}</td></tr></tbody></table><div class="mt-4 flex justify-between text-sm"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{pages}}</span><button :disabled="page>=pages" @click="load(page+1)">Próxima</button></div></div></PageShell></template>
<script setup lang="ts">/* eslint-disable @typescript-eslint/no-explicit-any */import{onMounted,reactive,ref}from'vue';import api from '@/plugins/axios';import PageShell from '@/components/PageShell.vue';const data=ref<any[]>([]),page=ref(1),pages=ref(1);const filters=reactive({search:'',document_status:'',authorization_status:'',treatment_status:'',billing_status:'',assessment_date:'',expected_start_date:''});const authStatuses=['NOT_READY','READY','IN_PROGRESS','PENDING','AUTHORIZED','DENIED','SESSION_TOKEN','NOT_REQUIRED'];const date=(v:string)=>v?new Date(v).toLocaleDateString('pt-BR'):'—';async function load(p=1){const response=await api.get('/guide-processes',{params:{...filters,page:p}});data.value=response.data.data;page.value=response.data.pagination.page;pages.value=response.data.pagination.pages||1}onMounted(()=>load());</script>
